public struct Esse3CoverageDeletable: Codable, Hashable, Sendable {
    /// codice che indica se la copertura è cancellabile
    public var returnCode: Int?
    /// eventuale messaggio con informazioni aggiuntive
    public var message: String?

    public init(
        returnCode: Int? = nil,
        message: String? = nil
    ) {
        self.returnCode = returnCode
        self.message = message
    }

    private enum CodingKeys: String, CodingKey {
        case returnCode = "retCode"
        case message = "msg"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.returnCode = container.decodeLenient(Int.self, forKey: .returnCode)
        self.message = container.decodeLenient(String.self, forKey: .message)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(returnCode, forKey: .returnCode)
        try container.encode(message, forKey: .message)
    }
}

